import Redis from "ioredis";

const redis = new Redis(process.env.REDIS_URL);

const CAPACITY = 100; // max tokens per client
const REFILL_RATE = 10; // tokens per second

interface BucketState {
  tokens: number;
  lastRefill: number; // epoch ms
}

/**
 * Token-bucket rate limiter for job-submission requests, backed by Redis
 * so every service instance shares the same limit per client.
 */
export class RateLimiter {
  constructor(private readonly redis: Redis) {}

  async allow(clientId: string): Promise<boolean> {
    const key = `rate_limit:${clientId}`;

    // 1) READ current state
    const raw = await this.redis.get(key);
    const now = Date.now();
    const state: BucketState = raw
      ? JSON.parse(raw)
      : { tokens: CAPACITY, lastRefill: now };

    // 2) REFILL based on elapsed time
    const elapsedSeconds = (now - state.lastRefill) / 1000;
    const refilled = Math.min(
      CAPACITY,
      state.tokens + elapsedSeconds * REFILL_RATE,
    );

    // 3) COMPARE
    if (refilled < 1) {
      await this.redis.set(
        key,
        JSON.stringify({ tokens: refilled, lastRefill: now }),
      );
      return false;
    }

    // 4) DECREMENT + WRITE BACK
    const newState: BucketState = { tokens: refilled - 1, lastRefill: now };
    await this.redis.set(key, JSON.stringify(newState));
    return true;
  }
}

/**
 * Alternative limiter that keeps counters in process memory instead of Redis.
 * Simpler and avoids a Redis round-trip, but only correct on a single instance.
 */
const buckets = new Map<string, BucketState>();

export class InMemoryRateLimiter {
  async allow(clientId: string): Promise<boolean> {
    const now = Date.now();
    const state = buckets.get(clientId) ?? { tokens: CAPACITY, lastRefill: now };

    const elapsedSeconds = (now - state.lastRefill) / 1000;
    const refilled = Math.min(CAPACITY, state.tokens + elapsedSeconds * REFILL_RATE);

    if (refilled < 1) {
      buckets.set(clientId, { tokens: refilled, lastRefill: now });
      return false;
    }

    buckets.set(clientId, { tokens: refilled - 1, lastRefill: now });
    return true;
  }
}

// --- existing test (passing) ---
describe("RateLimiter", () => {
  it("rejects requests once the bucket is empty", async () => {
    const limiter = new RateLimiter(redis);
    const clientId = "client-1";

    let allowedCount = 0;
    for (let i = 0; i < CAPACITY + 5; i++) {
      // eslint-disable-next-line no-await-in-loop
      const allowed = await limiter.allow(clientId);
      if (allowed) allowedCount++;
    }

    expect(allowedCount).toBe(CAPACITY);
  });
});
